qedit(n,3,'options.3.text','Do not grant implicit trust solely from network location; evaluate resource access using identity, device and policy','LocationsignalsallowedperNIST.',nist)
qreplace(n,3,'workedExample','Access is granted to an application, not to a network.','Access is scoped to the resources and operations required for a session, with reevaluation as policy dictates.','NISTbroaderthanapplication.',nist)
